def resolve_and_geolocate(host: str, timeout: float = 5.0, ipinfo_token: str | None = None) -> dict:
    """
    Resolve the given host to an IP address and fetch geolocation info from ipinfo.io.
    Robust to common errors (invalid host, network issues, JSON errors, API errors).

    Returns a dict with keys:
      - success: bool
      - ip: resolved IP address (str) or None
      - geolocation: dict returned by ipinfo.io (or None on error)
      - status_code: HTTP status code returned by ipinfo.io (int or None)
      - error: human-readable error message (or None on success)

    Notes:
      - Uses the 'requests' library (not 'rest_requests').
      - If ipinfo_token is provided it will be sent as ?token=TOKEN to ipinfo.io
      - Default timeout for DNS resolution + HTTP request is controlled by the timeout parameter.
    """
    # Local imports to keep the function self-contained when copied.
    import socket
    import ipaddress
    import requests
    from requests.exceptions import RequestException, Timeout, ConnectionError
    try:
        # Basic validation
        if not host or not isinstance(host, str):
            return {"success": False, "ip": None, "geolocation": None, "status_code": None,
                    "error": "host must be a non-empty string"}

        # If the host is already an IP address (v4 or v6), use it directly.
        try:
            ip_obj = ipaddress.ip_address(host)
            ip = str(ip_obj)
        except ValueError:
            # Not an IP literal; attempt DNS resolution (support IPv4/IPv6).
            try:
                # getaddrinfo may return multiple results; take the first.
                infos = socket.getaddrinfo(host, 0)
                if not infos:
                    return {"success": False, "ip": None, "geolocation": None, "status_code": None,
                            "error": f"DNS lookup returned no results for host: {host}"}
                # sockaddr[0] is address for both IPv4 and IPv6
                ip = infos[0][4][0]
            except socket.gaierror as e:
                return {"success": False, "ip": None, "geolocation": None, "status_code": None,
                        "error": f"DNS resolution error for host '{host}': {e}"}
            except Exception as e:
                return {"success": False, "ip": None, "geolocation": None, "status_code": None,
                        "error": f"Unexpected error during DNS resolution: {e}"}

        # Build ipinfo URL
        ipinfo_url = f"https://ipinfo.io/{ip}/json"
        if ipinfo_token:
            # ipinfo accepts token as a query parameter
            ipinfo_url = f"{ipinfo_url}?token={ipinfo_token}"

        # Query ipinfo.io
        headers = {"User-Agent": "resolve_and_geolocate/1.0"}
        try:
            resp = requests.get(ipinfo_url, headers=headers, timeout=timeout)
        except Timeout:
            return {"success": False, "ip": ip, "geolocation": None, "status_code": None,
                    "error": f"Request to ipinfo.io timed out after {timeout} seconds"}
        except ConnectionError as e:
            return {"success": False, "ip": ip, "geolocation": None, "status_code": None,
                    "error": f"Network error when contacting ipinfo.io: {e}"}
        except RequestException as e:
            return {"success": False, "ip": ip, "geolocation": None, "status_code": None,
                    "error": f"Error when contacting ipinfo.io: {e}"}

        status = resp.status_code
        if status != 200:
            # Try to extract message from response body, but don't raise on JSON errors.
            err_msg = None
            try:
                body = resp.json()
                # ipinfo may return {"error": {"title": "...", "message": "..."}}
                if isinstance(body, dict):
                    if "error" in body:
                        if isinstance(body["error"], dict):
                            err_msg = body["error"].get("message") or body["error"].get("title")
                        else:
                            err_msg = str(body["error"])
                    else:
                        # pick any helpful field
                        err_msg = body.get("message") or body.get("error") or str(body)
            except ValueError:
                err_msg = resp.text.strip() or None

            # Special hint for rate limiting
            if status == 429:
                hint = " Rate limited by ipinfo.io; consider supplying an ipinfo_token or retry later."
            else:
                hint = ""

            return {"success": False, "ip": ip, "geolocation": None, "status_code": status,
                    "error": f"ipinfo.io returned HTTP {status}: {err_msg or resp.reason}.{hint}"}

        # Parse JSON
        try:
            geo = resp.json()
        except ValueError:
            return {"success": False, "ip": ip, "geolocation": None, "status_code": status,
                    "error": "Failed to parse JSON response from ipinfo.io"}

        # Successful result
        return {"success": True, "ip": ip, "geolocation": geo, "status_code": status, "error": None}

    except Exception as e:
        # Catch-all unexpected errors
        return {"success": False, "ip": None, "geolocation": None, "status_code": None,
                "error": f"Unexpected error: {e}"}

