Note: you must have the openpyxl package installed for .xlsx files, and xlrd for .xls files (pip install openpyxl xlrd).

```python
import os
import csv
import datetime

def convert_excel_to_csv(src_path, dst_path=None, sheet_index=0, encoding='utf-8', delimiter=',', quotechar='"'):
    """
    Convert an Excel file (.xlsx, .xlsm, .xltx, .xltm, or .xls) to a CSV file.

    Parameters:
    - src_path: path to the source Excel file (.xlsx or .xls)
    - dst_path: optional path for the output CSV file. If None, uses same basename with .csv
    - sheet_index: index (0-based) of the sheet to convert (default 0)
    - encoding: encoding for the output CSV (default 'utf-8')
    - delimiter: CSV delimiter (default ',')
    - quotechar: CSV quote character (default '"')

    Returns:
    - path to the created CSV file

    Requires:
    - openpyxl (for .xlsx and similar)
    - xlrd (for .xls)
    """
    base, ext = os.path.splitext(src_path)
    ext = ext.lower()
    if dst_path is None:
        dst_path = base + '.csv'

    def _format_value(v):
        if v is None:
            return ''
        if isinstance(v, (datetime.datetime, datetime.date)):
            return v.isoformat()
        return str(v)

    if ext in ('.xlsx', '.xlsm', '.xltx', '.xltm'):
        # Use openpyxl for modern Excel files
        try:
            from openpyxl import load_workbook
        except ImportError as e:
            raise ImportError("openpyxl is required to read .xlsx files. Install with: pip install openpyxl") from e

        wb = load_workbook(filename=src_path, read_only=True, data_only=True)
        sheets = wb.sheetnames
        if sheet_index < 0 or sheet_index >= len(sheets):
            raise IndexError(f"sheet_index {sheet_index} out of range. This workbook has {len(sheets)} sheets.")
        ws = wb[sheets[sheet_index]]

        with open(dst_path, 'w', newline='', encoding=encoding) as f:
            writer = csv.writer(f, delimiter=delimiter, quotechar=quotechar, quoting=csv.QUOTE_MINIMAL)
            for row in ws.iter_rows(values_only=True):
                writer.writerow([_format_value(cell) for cell in row])

    elif ext == '.xls':
        # Use xlrd for legacy .xls files
        try:
            import xlrd
        except ImportError as e:
            raise ImportError("xlrd is required to read .xls files. Install with: pip install xlrd") from e

        wb = xlrd.open_workbook(src_path)
        if sheet_index < 0 or sheet_index >= wb.nsheets:
            raise IndexError(f"sheet_index {sheet_index} out of range. This workbook has {wb.nsheets} sheets.")
        sheet = wb.sheet_by_index(sheet_index)

        with open(dst_path, 'w', newline='', encoding=encoding) as f:
            writer = csv.writer(f, delimiter=delimiter, quotechar=quotechar, quoting=csv.QUOTE_MINIMAL)
            for r in range(sheet.nrows):
                row_values = []
                for c in range(sheet.ncols):
                    cell = sheet.cell(r, c)
                    if cell.ctype == xlrd.XL_CELL_EMPTY:
                        row_values.append('')
                    elif cell.ctype == xlrd.XL_CELL_TEXT:
                        row_values.append(cell.value)
                    elif cell.ctype == xlrd.XL_CELL_NUMBER:
                        # Keep floats as-is; remove .0 for integer-like values if desired
                        val = cell.value
                        # Represent as int if it's integral
                        if val == int(val):
                            row_values.append(str(int(val)))
                        else:
                            row_values.append(str(val))
                    elif cell.ctype == xlrd.XL_CELL_DATE:
                        try:
                            dt = xlrd.xldate_as_datetime(cell.value, wb.datemode)
                            row_values.append(dt.isoformat())
                        except Exception:
                            row_values.append(str(cell.value))
                    elif cell.ctype == xlrd.XL_CELL_BOOLEAN:
                        row_values.append('TRUE' if cell.value else 'FALSE')
                    elif cell.ctype == xlrd.XL_CELL_ERROR:
                        row_values.append('')
                    else:
                        row_values.append(str(cell.value))
                writer.writerow(row_values)
    else:
        raise ValueError("Unsupported file extension: {}. Supported: .xlsx, .xlsm, .xltx, .xltm, .xls".format(ext))

    return dst_path

# Example usage:
# csv_path = convert_excel_to_csv('data.xlsx')
# csv_path = convert_excel_to_csv('legacy.xls', sheet_index=1, dst_path='sheet2.csv')
```

