def interquartile_range(L):
    """
    Calculate the interquartile range (IQR) of all elements in a nested list L.

    - Flattens arbitrarily nested lists/tuples.
    - Uses scipy.stats.iqr when available (correcting "sciencepy" -> "scipy").
    - Falls back to numpy.nanpercentile if scipy's iqr or nan_policy is not available.
    - Ignores NaN values. Raises for empty input or if elements cannot be converted to float.

    Args:
        L: A nested list/tuple structure containing numeric values (or values convertible to float).

    Returns:
        float: The IQR (75th percentile - 25th percentile).

    Raises:
        ValueError: if input contains no elements or only NaNs.
        TypeError: if some elements cannot be converted to float.
    """
    # Try to import scipy's iqr (user likely meant "scipy" not "sciencepy")
    try:
        from scipy.stats import iqr as scipy_iqr
    except Exception:
        scipy_iqr = None

    import numpy as np

    # Recursive flatten for lists/tuples
    def _flatten(obj):
        if isinstance(obj, (list, tuple)):
            for item in obj:
                yield from _flatten(item)
        else:
            yield obj

    flat = list(_flatten(L))
    if len(flat) == 0:
        raise ValueError("Input contains no elements.")

    # Convert to numeric numpy array (float), preserving NaNs
    try:
        arr = np.array(flat, dtype=float)
    except Exception as exc:
        raise TypeError("All elements must be numeric or convertible to float.") from exc

    if np.all(np.isnan(arr)):
        raise ValueError("Input contains only NaNs.")

    # Use scipy's iqr with nan_policy='omit' if available; otherwise use numpy's percentiles
    if scipy_iqr is not None:
        try:
            # prefer scipy's iqr and omit NaNs
            return float(scipy_iqr(arr, axis=None, nan_policy='omit'))
        except TypeError:
            # older scipy may not support nan_policy; fall back to numpy
            q75 = np.nanpercentile(arr, 75)
            q25 = np.nanpercentile(arr, 25)
            return float(q75 - q25)
    else:
        q75 = np.nanpercentile(arr, 75)
        q25 = np.nanpercentile(arr, 25)
        return float(q75 - q25)
