def most_common_per_column(csv_path_or_buffer):
    """
    Read a CSV (with header) and return a dict mapping each column name to its most common value.
    Ties are broken by alphabetical order (case-insensitive, then case-sensitive as a tiebreaker).
    If the CSV is empty (no data rows or truly empty file), returns an empty dict.

    csv_path_or_buffer may be a filesystem path or any file-like object accepted by pandas.read_csv.
    All values are treated as strings (so alphabetical tie-breaking is well-defined).
    """
    import pandas as pd
    from collections import Counter

    try:
        # keep_default_na=False ensures empty fields remain empty strings rather than NaN
        df = pd.read_csv(csv_path_or_buffer, dtype=str, keep_default_na=False)
    except pd.errors.EmptyDataError:
        return {}

    # If no rows, treat as empty CSV per the specification
    if df.shape[0] == 0:
        return {}

    result = {}
    for col in df.columns:
        values = df[col].tolist()
        if not values:
            continue
        counts = Counter(values)
        max_count = max(counts.values())
        candidates = [val for val, cnt in counts.items() if cnt == max_count]
        # Sort alphabetically (case-insensitive first, then case-sensitive to stabilize)
        candidates.sort(key=lambda s: (s.lower(), s))
        result[col] = candidates[0]

    return result

