```python
def ocr_image_to_utf8(image_path, lang='eng', tesseract_cmd=None, return_source=False):
    """
    Open an image file, extract text with pytesseract, and convert the text encoding to a Python str (UTF-8).
    If OCR output is empty, fall back to reading image comment fields and EXIF UserComment.
    Parameters:
      - image_path: path to the image file
      - lang: language code(s) to pass to pytesseract (default 'eng')
      - tesseract_cmd: optional path to tesseract executable (sets pytesseract.pytesseract.tesseract_cmd)
      - return_source: if True returns (text, source) where source is 'ocr' or the metadata field used
    Returns:
      - text (str) or (text, source) if return_source True
    Requires:
      - pytesseract (pip install pytesseract)
      - Pillow (pip install pillow)
      - optionally chardet (pip install chardet) for better encoding detection
    """
    # local imports
    try:
        import pytesseract
    except Exception as e:
        raise ImportError("pytesseract is required: pip install pytesseract") from e
    try:
        from PIL import Image, ExifTags
    except Exception as e:
        raise ImportError("Pillow (PIL) is required: pip install pillow") from e

    # optionally set tesseract executable path
    if tesseract_cmd:
        pytesseract.pytesseract.tesseract_cmd = tesseract_cmd

    # helper: try to decode bytes to str using common encodings, optionally chardet
    def _decode_bytes(b):
        if not isinstance(b, (bytes, bytearray)):
            # if it's already a str, just return it
            return str(b) if b is not None else ''
        bs = bytes(b)
        # EXIF UserComment often has an 8-byte prefix describing encoding
        if len(bs) >= 8:
            prefix = bs[:8]
            # common EXIF prefixes: b'ASCII\0\0\0', b'UNICODE\0', b'JIS\0\0\0'
            if prefix.startswith(b'ASCII'):
                candidate = bs[8:]
                try:
                    return candidate.decode('ascii')
                except Exception:
                    pass
            if prefix.startswith(b'UNICODE'):
                candidate = bs[8:]
                try:
                    # EXIF UNICODE is typically UTF-16
                    return candidate.decode('utf-16')
                except Exception:
                    pass
            if prefix.startswith(b'JIS'):
                candidate = bs[8:]
                # try common Japanese encodings
                for enc in ('shift_jis', 'euc_jp', 'iso2022_jp'):
                    try:
                        return candidate.decode(enc)
                    except Exception:
                        pass
        # try utf-8, utf-16, cp1252, latin-1
        for enc in ('utf-8', 'utf-16', 'cp1252', 'latin-1'):
            try:
                return bs.decode(enc)
            except Exception:
                pass
        # try chardet if available
        try:
            import chardet
            det = chardet.detect(bs)
            enc = det.get('encoding')
            if enc:
                try:
                    return bs.decode(enc, errors='replace')
                except Exception:
                    pass
        except Exception:
            pass
        # last resort: latin-1 decode (never fails)
        return bs.decode('latin-1', errors='replace')

    # helper: collect candidate metadata strings from the image
    def _collect_metadata_texts(img):
        candidates = []
        info = getattr(img, 'info', {}) or {}
        # common keys
        for k in ('comment', 'Comment', 'COM', 'Description', 'description', 'Text'):
            if k in info:
                candidates.append(info[k])
        # include all info values in case some formats store textual chunks under other keys
        for v in info.values():
            if v is not None:
                candidates.append(v)
        # EXIF
        try:
            exif = img.getexif()
        except Exception:
            exif = None
        if exif:
            # Map numeric exif tags to names
            tag_map = {v: k for k, v in ExifTags.TAGS.items()}
            # Common textual EXIF tags: ImageDescription, UserComment, XPComment, XPTitle, XPSubject
            for tag_no, val in exif.items():
                name = ExifTags.TAGS.get(tag_no, str(tag_no))
                if name in ('ImageDescription', 'UserComment', 'XPComment', 'XPTitle', 'XPSubject'):
                    candidates.append(val)
                # also include any other short textual exif entries
                elif isinstance(val, (bytes, str, bytearray)):
                    candidates.append(val)
        return candidates

    # open image
    try:
        img = Image.open(image_path)
    except Exception as e:
        raise IOError(f"Cannot open image {image_path}: {e}") from e

    # try OCR first
    ocr_text = ''
    ocr_source = 'ocr'
    try:
        ocr_text = pytesseract.image_to_string(img, lang=lang)
        if ocr_text is None:
            ocr_text = ''
        else:
            # normalize to str
            if isinstance(ocr_text, bytes):
                ocr_text = _decode_bytes(ocr_text)
            else:
                ocr_text = str(ocr_text)
            ocr_text = ocr_text.strip()
    except Exception:
        # if pytesseract not installed/configured correctly or tesseract not found,
        # just treat as empty and fall back to metadata
        ocr_text = ''

    if ocr_text:
        return (ocr_text, ocr_source) if return_source else ocr_text

    # fallback: inspect metadata/comment fields
    candidates = _collect_metadata_texts(img)
    for cand in candidates:
        if cand is None:
            continue
        if isinstance(cand, str):
            s = cand.strip()
        else:
            try:
                s = _decode_bytes(cand).strip()
            except Exception:
                s = ''
        if s:
            # first non-empty candidate
            return (s, 'metadata') if return_source else s

    # nothing found
    return (u'', 'none') if return_source else ''
